/// Records the URL of every request and answers with an empty JSON object.
struct UrlRecordingApiClient {
    urls: std::sync::Mutex<Vec<String>>,
}

impl petstore::api_client::ApiClient for UrlRecordingApiClient {
    fn send_request(
        &self,
        _method: &str,
        url: &str,
        _headers: &HashMap<String, String>,
        _body: Option<&petstore::api_client::RequestBody>,
    ) -> Pin<
        Box<
            dyn Future<
                    Output = Result<
                        petstore::api_http_response::ApiHttpResponse,
                        Box<dyn std::error::Error + Send + Sync>,
                    >,
                > + Send
                + '_,
        >,
    > {
        self.urls.lock().unwrap().push(url.to_string());
        Box::pin(async {
            Ok(petstore::api_http_response::ApiHttpResponse::new(
                200,
                "{}".to_string(),
                HashMap::from([("Content-Type".to_string(), "application/json".to_string())]),
            ))
        })
    }
}

fn new_pet_api_recording_urls() -> (PetApi, Arc<UrlRecordingApiClient>) {
    let client = Arc::new(UrlRecordingApiClient {
        urls: std::sync::Mutex::new(Vec::new()),
    });
    let config = ConfigurationBuilder::new()
        .base_url("http://localhost")
        .build();
    (PetApi::new(client.clone(), config, None), client)
}

