/* F1068: the summary call that succeeds. The matrix date segment, the required
 * cookie and the date array reach the wire, and the text/plain answer comes
 * back as the text. */
#[tokio::test]
async fn test_pet_api_get_pet_summary_succeeds_with_a_text_plain_answer() {
    let listener = TcpListener::bind("127.0.0.1:0").expect("failed to bind");
    let base_url = format!("http://{}", listener.local_addr().unwrap());
    let (tx, rx) = std::sync::mpsc::channel::<String>();
    thread::spawn(move || {
        if let Some(stream) = listener.incoming().next() {
            let mut stream = stream.unwrap();
            let mut buf = [0u8; 4096];
            let n = stream.read(&mut buf).unwrap_or(0);
            let _ = tx.send(String::from_utf8_lossy(&buf[..n]).to_string());
            let body = "all good";
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
                body.len(),
                body
            );
            let _ = std::io::Write::write_all(&mut stream, response.as_bytes());
        }
    });
    thread::sleep(std::time::Duration::from_millis(50));
    let config = ConfigurationBuilder::new().base_url(&base_url).build();
    let api = PetApi::new(Arc::new(DefaultApiClient::new(None)), config, None);
    let as_of = chrono::NaiveDate::from_ymd_opt(2024, 1, 31).expect("a valid date");
    let days = vec![
        chrono::NaiveDate::from_ymd_opt(2024, 2, 1).expect("a valid date"),
        chrono::NaiveDate::from_ymd_opt(2024, 2, 2).expect("a valid date"),
    ];
    let opts = GetPetSummaryOptions::new("sess".to_string()).days(days);

    let summary = api
        .get_pet_summary(1, as_of, Some(&opts))
        .await
        .expect("a text/plain answer is the text");

    assert_eq!("all good", summary);
    let head = rx.recv().expect("expected a captured request");
    let request_line = head.lines().next().unwrap_or_default().to_string();
    assert!(
        request_line.contains("/pet/1/summary/;asOf=2024-01-31"),
        "{}",
        request_line
    );
    assert!(
        request_line.contains("days=2024-02-01&days=2024-02-02"),
        "{}",
        request_line
    );
    assert!(
        head.to_lowercase().contains("cookie: session=sess"),
        "{}",
        head
    );
}

